/** Real local HTTP sockets and Ed25519 envelopes, production encrypted LocalStore.
 * The explicit test connector is not a Tor/native/production-server acceptance test. */
class CommunityClientTest {
 @TempDir Path dir;
 static final String ONION="a".repeat(56)+".onion",SECRET="РАЗРЕШЁННЫЙ-КЭШ-89173";
 static final char[] PASSWORD="independent secure profile password".toCharArray();
 MutableClock clock=new MutableClock();
 static final class MutableClock extends Clock {long time=1_800_000_000_000L;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return Instant.ofEpochMilli(time);}public long millis(){return time;}}
 LocalStore local()throws Exception{return new LocalStore(dir,PASSWORD,clock,200_000,20*1024*1024);}
 static JsonObject args(String id){JsonObject o=new JsonObject();o.addProperty("id",id);return o;}
 static JsonObject data(String id,boolean offline){JsonObject o=new JsonObject(),p=new JsonObject();o.addProperty("id",id);o.addProperty("body",SECRET);p.addProperty("offlineAllowed",offline);o.add("policy",p);return o;}
 @Test void authenticatedRequestAndPinnedResponseCacheRemainEncrypted()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.data=data("one",true);String identity=l.identity().userId();JsonObject r=c.rpc("content.library.get",args("one"));assertEquals(SECRET,r.get("body").getAsString());assertTrue(server.verified.get());assertEquals(identity,CommunityAuth.id(Base64.getDecoder().decode(server.headers.get().get("aegis-key"))));assertEquals(Set.of("action","data"),server.request.get().keySet());assertEquals(ONION,server.host.get());assertTrue(c.offline("content.library.get",args("one")).get("offlineCopy").getAsBoolean());try(var files=Files.walk(dir)){for(Path f:files.filter(Files::isRegularFile).toList()){String raw=new String(Files.readAllBytes(f),StandardCharsets.ISO_8859_1);assertFalse(raw.contains("89173"));assertFalse(raw.contains(ONION));}}assertEquals(identity,l.identity().userId());}}
 @Test void offlineDeniedWithoutExplicitPolicyAndExpires()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.data=data("one",false);c.rpc("content.library.get",args("one"));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));server.data=data("two",true);c.rpc("content.library.get",args("two"));clock.time+=300_001;assertThrows(IOException.class,()->c.offline("content.library.get",args("two")));}}
 @Test void serverEpochChangeInvalidatesPreviousAuthorizedCache()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.data=data("one",true);c.rpc("content.library.get",args("one"));server.epoch=2;server.data=data("two",true);c.rpc("content.library.get",args("two"));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));assertEquals("two",c.offline("content.library.get",args("two")).get("id").getAsString());}}
 @Test void signedDenialClearsCacheAndSafeErrorIsBounded()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.data=data("one",true);c.rpc("content.library.get",args("one"));server.denied=true;CommunityClient.Rejected e=assertThrows(CommunityClient.Rejected.class,()->c.rpc("content.library.get",args("one")));assertEquals("NOT_FOUND",e.code());assertFalse(e.getMessage().contains("\n"));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));}}
 @Test void wrongPinnedServerKeyAndChangedBodyNeverAccepted()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.tampered=true;assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));}}
 @Test void signedDuplicateJsonAndMalformedUtf8Rejected()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.raw="{\"ok\":true,\"ok\":false,\"data\":{}}".getBytes(StandardCharsets.UTF_8);assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));server.raw=new byte[]{'{','"','x','"',':','"',(byte)0xff,'"','}'};assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));}}
 @Test void duplicateHttpHeadersAndTruncatedBodyRejected()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.duplicateHeaders=true;assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));server.duplicateHeaders=false;server.truncated=true;assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));}}
 @Test void noConfiguredServiceOrClearnetAddressCausesNoConnection()throws Exception {try(var l=local()){AtomicInteger attempts=new AtomicInteger();try(var c=new CommunityClient(l,clock,(host,port)->{attempts.incrementAndGet();throw new IOException();})){assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));try(var server=new Fixture()){assertThrows(IOException.class,()->c.configure("https://example.org",80,server.key()));assertThrows(IOException.class,()->c.configure(ONION,0,server.key()));}assertEquals(0,attempts.get());}}}
 @Test void profileIdentityAndEncryptedOfflineCacheSurviveUncleanClientRestart()throws Exception {String identity;try(var server=new Fixture()){LocalStore first=local();CommunityClient old=server.client(first,clock);server.data=data("one",true);identity=first.identity().userId();old.rpc("content.library.get",args("one"));first.close();try(var second=local();var restored=new CommunityClient(second,clock,(a,b)->{throw new IOException("Offline fixture");})){assertEquals(identity,second.identity().userId());assertTrue(restored.configured());assertEquals(SECRET,restored.offline("content.library.get",args("one")).get("body").getAsString());}finally{old.close();}}}
 @Test void damagedOptionalCacheCannotBreakAccountIdentity()throws Exception {try(var l=local();var server=new Fixture()){String identity=l.identity().userId();try(var c=server.client(l,clock)){c.rpc("content.library.get",args("one"));}Path f=dir.resolve("lifecycle/community-v1.enc");byte[]encrypted=Files.readAllBytes(f);encrypted[encrypted.length-1]^=1;Files.write(f,encrypted);try(var damaged=new CommunityClient(l,clock,(a,b)->{throw new IOException();})){assertTrue(damaged.damaged());assertFalse(damaged.configured());assertEquals(identity,l.identity().userId());assertThrows(IOException.class,()->damaged.rpc("content.library.get",args("one")));}}}
 @Test void closingClientClearsOfflineCopyAndRejectsNewRequests()throws Exception {try(var l=local();var server=new Fixture()){var c=server.client(l,clock);c.rpc("content.library.get",args("one"));c.close();assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));try(var restored=new CommunityClient(l,clock,(a,b)->{throw new IOException();})){assertThrows(IOException.class,()->restored.offline("content.library.get",args("one")));}}}
 @Test void clockRollbackDoesNotExtendOfflineLifetime()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){c.rpc("content.library.get",args("one"));clock.time-=600_000;assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));}}

 @Test void responseMustBindExactActorAndRequestHash()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){
  for(String field:List.of("requestIdentity","requestSha256")){server.mutate=o->o.addProperty(field,"0".repeat(64));assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));server.mutate=o->o.remove(field);assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));}assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));}}
 @Test void responseStatusAndEpochCannotBeCoercedFromOtherJsonTypes()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){
  for(JsonElement invalid:List.of(new JsonPrimitive("true"),new JsonPrimitive(1),JsonNull.INSTANCE,new JsonObject())){server.mutate=o->o.add("ok",invalid);assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));}
  for(JsonElement invalid:List.of(new JsonPrimitive("1"),new JsonPrimitive(-1),new JsonPrimitive(1.25),new JsonPrimitive(true),JsonNull.INSTANCE)){server.mutate=o->o.add("authorizationEpoch",invalid);assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));}}}
 @Test void staleSignedEpochCannotRepopulateRevokedCache()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.epoch=2;c.rpc("content.library.get",args("two"));server.epoch=1;assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));}}
 @Test void nonBooleanOfflineFlagDoesNotAuthorizeCache()throws Exception {try(var l=local();var server=new Fixture();var c=server.client(l,clock)){server.data=data("one",false);server.data.getAsJsonObject("policy").addProperty("offlineAllowed","true");c.rpc("content.library.get",args("one"));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));}}
 @Test void closeCancelsActiveSocketWithoutLateCacheResurrection()throws Exception {try(var l=local();var server=new Fixture()){var c=server.client(l,clock);server.hang=true;ExecutorService pool=Executors.newSingleThreadExecutor();try{Future<IOException> request=pool.submit(()->{try{c.rpc("content.library.get",args("one"));return null;}catch(IOException e){return e;}});assertTrue(server.seen.await(3,TimeUnit.SECONDS));c.close();assertNotNull(request.get(3,TimeUnit.SECONDS));assertThrows(IOException.class,()->c.offline("content.library.get",args("one")));try(var restored=new CommunityClient(l,clock,(a,b)->{throw new IOException();})){assertThrows(IOException.class,()->restored.offline("content.library.get",args("one")));}}finally{c.close();pool.shutdownNow();assertTrue(pool.awaitTermination(3,TimeUnit.SECONDS));}}}
 @Test void atMostFourConcurrentNetworkRequestsAreOpened()throws Exception {try(var l=local();var server=new Fixture()){var c=server.client(l,clock);server.hang=true;ExecutorService pool=Executors.newFixedThreadPool(4);try{List<Future<?>> pending=new ArrayList<>();for(int i=0;i<4;i++)pending.add(pool.submit(()->{assertThrows(IOException.class,()->c.rpc("content.library.get",args("one")));}));long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(server.connections.get()<4&&System.nanoTime()<deadline)Thread.onSpinWait();assertEquals(4,server.connections.get());assertThrows(IOException.class,()->c.rpc("content.library.get",args("fifth")));assertEquals(4,server.connections.get());c.close();for(Future<?> f:pending)f.get(3,TimeUnit.SECONDS);}finally{c.close();pool.shutdownNow();assertTrue(pool.awaitTermination(3,TimeUnit.SECONDS));}}}

 static final class Fixture implements AutoCloseable {
  final ServerSocket listener;final ExecutorService worker=Executors.newSingleThreadExecutor();final KeyPair pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
  volatile JsonObject data=data("one",true);volatile byte[]raw;volatile long epoch=1;volatile boolean denied,tampered,duplicateHeaders,truncated,hang;volatile java.util.function.Consumer<JsonObject>mutate;final AtomicInteger connections=new AtomicInteger();final CountDownLatch seen=new CountDownLatch(1);
  final AtomicBoolean verified=new AtomicBoolean();final AtomicReference<String>host=new AtomicReference<>();final AtomicReference<JsonObject>request=new AtomicReference<>();final AtomicReference<Map<String,String>>headers=new AtomicReference<>();
  Fixture()throws Exception {listener=new ServerSocket();listener.bind(new InetSocketAddress(InetAddress.getLoopbackAddress(),0));worker.submit(()->{while(!listener.isClosed())try(Socket s=listener.accept()){serve(s);}catch(Exception e){if(!listener.isClosed())throw new RuntimeException(e);}return null;});}
  String key(){return Base64.getEncoder().encodeToString(pair.getPublic().getEncoded());}
  CommunityClient client(LocalStore local,Clock clock)throws Exception {CommunityClient c=new CommunityClient(local,clock,(onion,port)->{host.set(onion);connections.incrementAndGet();return new Socket(InetAddress.getLoopbackAddress(),listener.getLocalPort());});c.configure(ONION,80,key());return c;}
  void serve(Socket socket)throws Exception {socket.setSoTimeout(5000);DataInputStream in=new DataInputStream(socket.getInputStream());String first=line(in);if(!first.equals("POST /api/v1 HTTP/1.1"))throw new IOException("Fixture request route");Map<String,String>h=new HashMap<>();for(int n=0;n<64;n++){String line=line(in);if(line.isEmpty())break;int colon=line.indexOf(':');h.put(line.substring(0,colon).toLowerCase(Locale.ROOT),line.substring(colon+1).strip());}headers.set(h);int size=Integer.parseInt(h.get("content-length"));byte[]body=in.readNBytes(size);String audience=CommunityAuth.id(pair.getPublic().getEncoded()),nonce=h.get("aegis-nonce");verified.set(CommunityAuth.verify(Base64.getDecoder().decode(h.get("aegis-key")),CommunityAuth.requestBytes(audience,Long.parseLong(h.get("aegis-time")),nonce,body),Base64.getDecoder().decode(h.get("aegis-signature"))));request.set(CommunityJson.parse(body));seen.countDown();if(hang){in.read();return;}JsonObject response=new JsonObject();response.addProperty("requestIdentity",CommunityAuth.id(Base64.getDecoder().decode(h.get("aegis-key"))));response.addProperty("requestSha256",CommunityAuth.id(CommunityAuth.requestBytes(audience,Long.parseLong(h.get("aegis-time")),nonce,body)));response.addProperty("ok",!denied);response.addProperty("authorizationEpoch",epoch);if(denied){JsonObject error=new JsonObject();error.addProperty("code","NOT_FOUND");error.addProperty("message","Материал недоступен\n");response.add("error",error);}else response.add("data",data);if(mutate!=null)mutate.accept(response);byte[]out=raw==null?response.toString().getBytes(StandardCharsets.UTF_8):raw.clone();byte[]signature=CommunityAuth.sign(pair.getPrivate(),CommunityAuth.responseBytes(audience,nonce,out));if(tampered&&out.length>3)out[out.length-2]^=1;String head="HTTP/1.1 200 OK\r\nContent-Length: "+out.length+"\r\nAEGIS-Signature: "+Base64.getEncoder().encodeToString(signature)+"\r\n"+(duplicateHeaders?"Content-Length: "+out.length+"\r\n":"")+"\r\n";socket.getOutputStream().write(head.getBytes(StandardCharsets.US_ASCII));socket.getOutputStream().write(out,0,truncated?out.length-1:out.length);socket.getOutputStream().flush();}
  static String line(DataInputStream in)throws IOException {ByteArrayOutputStream b=new ByteArrayOutputStream();for(int n=0;n<16384;n++){int c=in.read();if(c<0)throw new EOFException();if(c=='\r'){if(in.read()!='\n')throw new IOException();return b.toString(StandardCharsets.US_ASCII);}b.write(c);}throw new IOException();}
  public void close()throws IOException{listener.close();worker.shutdownNow();try{assertTrue(worker.awaitTermination(5,TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IOException("Fixture interrupted",e);}}
 }
}
